            'POST',
            $operationHost . $resourcePath,
            // Query.
            [
            ],
            // Headers.
            array_merge(
                [
                ],
                $headers
            ),
            // Form Params
            [
                'thankyou' => isset($thankyou) ? ObjectSerializer::toFormValue($thankyou) : null,
            ],
            ''
        );
    }
}